#include <bits/stdc++.h>
using namespace std;

#define all(x) (x).begin(), (x).end()
#define sz(x) (int)(x).size()

bool solve() {
    int n; cin >> n;
    vector<pair<int, int>> pts(n);
    for (auto &[x, y] : pts)
        cin >> x >> y;
    sort(all(pts));
    vector<int> ys;
    for (auto [x, y] : pts)
        ys.push_back(y);
    
    // int ctr = 0, mx = pts[0].second;
    // for (int i = 1; i < n; i++) {
    //     if (pts[i].second < mx)
    //         ctr++;
    //     mx = max(mx, pts[i].second);
    // }
    // return ctr <= 1;

    int lo = *min_element(all(ys)), hi = *max_element(all(ys));
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        vector<int> top, bot;
        for (int i = 0; i < n; i++) {
            if (ys[i] >= mid)
                top.push_back(ys[i]);
            else
                bot.push_back(ys[i]);
        }
        bool top_dec = false, bot_dec = false;
        for (int i = 1; i < sz(top); i++)
            if (top[i] < top[i - 1])
                top_dec = true;
        for (int i = 1; i < sz(bot); i++)
            if (bot[i] < bot[i - 1])
                bot_dec = true;
        if (top_dec)
            lo = mid + 1;
        else if (bot_dec)
            hi = mid - 1;
        else
            return true;
    }
    
    return false;
}

int main() {
	int T; cin >> T;
	while (T--) {
	    cout << (solve() ? "YES": "NO") << "\n";
	}
}
